#After filtering packets with: data.data and wlan.ta == a4:83:e7:4a:7f:2c and wlan.fc.retry == 0
#I've selected the two packets with IV 0x00000000000C because one of them has the longest data length in the pcap

ct1_bytes = bytes.fromhex("")
ct2_bytes = bytes.fromhex("")

with open("expense-form.txt", 'rb') as f:

    pt1 = f.read()
    print(type(pt1))

    for i in range(50):

        val = bytes(c1 ^ c2 for c1, c2 in zip(ct1_bytes, ct2_bytes))
        # print(type(val))

        pt2 = bytes(p1 ^ v for p1, v in zip(pt1, val[i:]))

        if b'netsec' in pt2:
            print(pt2)
            break